    private static IScalarValue Read_cirScalarValue(ref MessagePackReader reader) =>
        Discriminator(reader, "a") switch
        {
            "null" => Read_attributeNull(ref reader),
            "bool" => Read_attributeBoolean(ref reader),
            "char" => Read_attributeChar(ref reader),
            "i8" => Read_attributeInt8(ref reader),
            "u8" => Read_attributeUInt8(ref reader),
            "i16" => Read_attributeInt16(ref reader),
            "u16" => Read_attributeUInt16(ref reader),
            "i32" => Read_attributeInt32(ref reader),
            "u32" => Read_attributeUInt32(ref reader),
            "i64" => Read_attributeInt64(ref reader),
            "u64" => Read_attributeUInt64(ref reader),
            "f32" => Read_attributeFloat32(ref reader),
            "f64" => Read_attributeFloat64(ref reader),
            "text" => Read_attributeText(ref reader),
            "utf16" => Read_attributeUtf16(ref reader),
            _ => throw new FormatException(),
        };

    private static void Write_cirScalarValue(ref MessagePackWriter writer, IScalarValue node, int depth)
    {
        switch (node)
        {
            case AttributeArgument.NullValue value: Write_attributeNull(ref writer, value, depth); break;
            case AttributeArgument.BooleanValue value: Write_attributeBoolean(ref writer, value, depth); break;
            case AttributeArgument.CharValue value: Write_attributeChar(ref writer, value, depth); break;
            case AttributeArgument.Int8Value value: Write_attributeInt8(ref writer, value, depth); break;
            case AttributeArgument.UInt8Value value: Write_attributeUInt8(ref writer, value, depth); break;
            case AttributeArgument.Int16Value value: Write_attributeInt16(ref writer, value, depth); break;
            case AttributeArgument.UInt16Value value: Write_attributeUInt16(ref writer, value, depth); break;
            case AttributeArgument.Int32Value value: Write_attributeInt32(ref writer, value, depth); break;
            case AttributeArgument.UInt32Value value: Write_attributeUInt32(ref writer, value, depth); break;
            case AttributeArgument.Int64Value value: Write_attributeInt64(ref writer, value, depth); break;
            case AttributeArgument.UInt64Value value: Write_attributeUInt64(ref writer, value, depth); break;
            case AttributeArgument.Float32Value value: Write_attributeFloat32(ref writer, value, depth); break;
            case AttributeArgument.Float64Value value: Write_attributeFloat64(ref writer, value, depth); break;
            case AttributeArgument.TextValue value: Write_attributeText(ref writer, value, depth); break;
            case AttributeArgument.Utf16Value value: Write_attributeUtf16(ref writer, value, depth); break;
            default: throw new FormatException();
        }
    }

