    private static CirCatchClause Read_cirCatchClause(ref MessagePackReader reader)
    {
        var count = ReadMap(ref reader);
        ulong seen = 0;
        TypeNode field_excType = default!;
        OptionalField<string> field_var = default!;
        ICirStatement[] field_body = default!;
        for (var i = 0; i < count; i++)
