            {
                case "excType":
                    Seen(ref seen, 1UL);
                    field_excType = Read_type(ref reader);
                    break;
                case "var":
                    Seen(ref seen, 2UL);
                    field_var = OptionalField<string>.Of(Read_value1(ref reader));
                    break;
                case "body":
                    Seen(ref seen, 4UL);
                    field_body = Read_value214(ref reader);
                    break;
                default: throw new FormatException();
            }
        }
        if ((seen & 5UL) != 5UL) throw new FormatException();
        reader.Depth--;
        var value = new CirCatchClause { ExcType = field_excType, Var = field_var, Body = field_body };
        return value;
